#include <stdio.h>
#include <string.h>

int main(void) {
    int n;
    char s[105];

    scanf("%d", &n);
    scanf("%s", s);

    int ans = n;  // typing all characters one by one

    for (int len = 1; len * 2 <= n; len++) {
        int ok = 1;
        for (int i = 0; i < len; i++) {
            if (s[i] != s[len + i]) {
                ok = 0;
                break;
            }
        }
        if (ok) {
            int ops = len + (n - 2 * len) + 1; // type len, copy once, type rest
            if (ops < ans) ans = ops;
        }
    }

    printf("%d\n", ans);
    return 0;
}

