import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String s = sc.next();

        int best = n; // no copy, just type all characters

        for (int i = 1; i <= n / 2; i++) {
            // Check if s[i..2i-1] == s[0..i-1]
            boolean valid = true;
            for (int j = 0; j < i; j++) {
                if (s.charAt(i + j) != s.charAt(j)) {
                    valid = false;
                    break;
                }
            }
            if (valid) {
                int ops = i + 1 + (n - 2 * i);
                best = Math.min(best, ops);
            }
        }

        System.out.println(best);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        String s = br.readLine().trim();

        int ans = n; // type all characters one by one

        // Suppose we first type k characters manually, then (optionally) copy them once.
        // After copying, the built string becomes s[0..k-1] + s[0..k-1],
        // so this is possible only if s[0..k-1] == s[k..2k-1].
        // Then total operations = k (manual typing) + 1 (copy) + (n - 2k) remaining chars.
        for (int k = 1; 2 * k <= n; k++) {
            boolean ok = true;
            for (int i = 0; i < k; i++) {
                if (s.charAt(i) != s.charAt(i + k)) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                ans = Math.min(ans, k + 1 + (n - 2 * k));
            }
        }

        System.out.println(ans);
    }
}
